#!/usr/bin/env node
// GENERATED by tools/docs-theme.mjs in the GaugeWright repository, which owns
// the documentation theme (DR-0093). Do not edit this file: it verifies itself
// against the digest below, so a local edit fails this repository's own gate.
// Change the theme there and re-render.
//
//   node scripts/check-docs-theme.mjs
//
// It answers two different questions, and both matter.
//
// The first is whether this repository still carries the theme it was given.
// The shared region of the stylesheet, the masthead template, the mark, and the
// faces are owned upstream; a hand edit here has to fail close to whoever made
// it rather than wait for a cross-repository sweep to notice.
//
// The second is whether the theme reached the built page at all. `mkdocs build
// --strict` fails on a missing `custom_dir`, but it resolves neither
// `extra_css` nor anything a theme override references: delete the brand
// stylesheet or the mark, rebuild, and the build still exits zero while the
// site serves an unstyled header and a broken image. So this reads the built
// site, not the source tree — a file present in `docs/` that mkdocs never
// copied, or a stylesheet the template never linked, is exactly the failure the
// source tree cannot show.

import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";

const SOURCE_DIGEST = "00b6cf5cff5c49e450dfb546ad331f1f0cdf62db904763318ca096f16f34849f";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

const BLOCK_BEGIN = "/* BEGIN GAUGEWRIGHT DOCS THEME v1";
const BLOCK_END = "/* END GAUGEWRIGHT DOCS THEME v1 */";

const failures = [];
const fail = (message) => failures.push(message);

function read(rel) {
  const at = path.join(repoRoot, rel);
  return fs.existsSync(at) ? fs.readFileSync(at, "utf8") : null;
}

// ---- 1. What this repository carries is what was rendered into it ----------

// The rendered manifest: every owned path with the digest of its contents at
// render time. Written by the projector directly beneath this comment.
const MANIFEST = {
  "stylesheet": "docs/assets/brand.css",
  "block": "e558c5d309512c298896a8fcbff903eace0da38ee43f532f4b81b1b8ff10e41d",
  "files": {
    "overrides/partials/logo.html": "4f71dfbe0ac492daf371802423b0ba243bf9902c1d39a480c13abeec7fb5716e",
    "docs/assets/fonts/commit-mono-v1.143.woff2": "f342ca6c3f2597e6c0fcd84b3f3ed64d3ce5bdb6d0af19d190d645a558b1cf29",
    "docs/assets/fonts/gaugewright-chrome-latin-ext-italic.woff2": "3fe0f32c9ef230908eb10bcc2a27336c5fde6a51fd2fd40e79a2a97a0f5277dd",
    "docs/assets/fonts/gaugewright-chrome-latin-ext-regular.woff2": "b80c81d54a9c808a1b377bc0b2f7296a26acae16cb3b8c999c2c9be3c4ee5b2b",
    "docs/assets/fonts/gaugewright-chrome-latin-italic.woff2": "9217d5af7ec046eb8d99f8151c0956818efe76af3952bedc4defd2ca13a96d94",
    "docs/assets/fonts/gaugewright-chrome-latin-regular.woff2": "4503e1a1ce654910e0e8c7e5c65660224c1eb513fbd99294f316f56ecb425333",
    "docs/assets/fonts/ibm-plex-serif-latin-400-italic.woff2": "d3f861b1ca55e50ca94de4c1756cb0d67c73de615172adf6b5b2078d939c723a",
    "docs/assets/fonts/ibm-plex-serif-latin-400.woff2": "cb2c5eee2c0a43ff30d2365407c7bc8b20e3bd90720a4a64102ba0b328022a02",
    "docs/assets/fonts/ibm-plex-serif-latin-700.woff2": "886ea167faf6610c3448a7dd058dbe7c7438f710229c9ff52343ef006960939c",
    "docs/assets/fonts/ibm-plex-serif-latin-ext-400-italic.woff2": "68091cb647810f7ac24fb72fe7ac506ffc4769ef51435a87969345249fc7f035",
    "docs/assets/fonts/ibm-plex-serif-latin-ext-400.woff2": "8b4077bd28d36819590924090252e811d4d0b2c78cb4bf1e4abe46d7428a2781",
    "docs/assets/fonts/ibm-plex-serif-latin-ext-700.woff2": "4c47e5be83b18b0851ffb58d6ec94ef439bd52a190b66ea479cfb19298720f68",
    "docs/assets/fonts/OFL-CommitMono.txt": "005e08f22d472be5139dcaf876dbed7ce8f17a501cd180c3259ad2aaf27237fe",
    "docs/assets/fonts/OFL-GaugeWrightChrome.txt": "9c9ee5ec82bbcd11d95c8732c9924f0fd58743e4c14dfdebd8a898323f6a0be7",
    "docs/assets/fonts/OFL-IBMPlexSerif.txt": "7e6b2818edbd8f6a01ae80641cc8f16a51080d08fb4e532be3a0b6f74adb07da",
    "docs/assets/mark-clear-64.png": "7fcd1d156b29b9ad25b14bd44d5f8c0b4d35774bffd3594b6ac9308b8caa8fa4"
  }
};

for (const [rel, want] of Object.entries(MANIFEST.files)) {
  const at = path.join(repoRoot, rel);
  if (!fs.existsSync(at)) {
    fail(`${rel} is missing; it is owned by the GaugeWright repository`);
    continue;
  }
  const have = crypto.createHash("sha256").update(fs.readFileSync(at)).digest("hex");
  if (have !== want) {
    fail(`${rel} does not match what was rendered here; it is owned by the GaugeWright repository`);
  }
}

// The stylesheet is the one file this repository may legitimately add to, so
// only its marked region is compared. Everything outside the markers is local.
const stylesheet = read(MANIFEST.stylesheet);
if (stylesheet === null) {
  fail(`${MANIFEST.stylesheet} is missing`);
} else {
  const begins = stylesheet.split(BLOCK_BEGIN).length - 1;
  const ends = stylesheet.split(BLOCK_END).length - 1;
  if (begins !== 1 || ends !== 1) {
    fail(`${MANIFEST.stylesheet} does not carry exactly one shared-theme block`);
  } else {
    const start = stylesheet.indexOf(BLOCK_BEGIN);
    const finish = stylesheet.indexOf(BLOCK_END) + BLOCK_END.length;
    const block = stylesheet.slice(start, finish);
    const have = crypto.createHash("sha256").update(block, "utf8").digest("hex");
    if (have !== MANIFEST.block) {
      fail(
        `the shared-theme block in ${MANIFEST.stylesheet} is stale or locally edited; `
          + "it is owned by the GaugeWright repository",
      );
    }
  }
}

// ---- 2. The theme reached the built site ----------------------------------

// mkdocs.yml names the output directory. Read it with a line match rather than
// a YAML parser: the parser would arrive as a transitive dependency of the docs
// toolchain, and a docs toolchain change would then take this check with it.
const mkdocs = read("mkdocs.yml");
const siteDir = mkdocs?.match(/^site_dir:\s*(\S+)/m)?.[1];
if (!siteDir) {
  fail("mkdocs.yml declares no site_dir");
} else {
  const site = path.resolve(repoRoot, siteDir);
  if (!fs.existsSync(site)) {
    fail(`${siteDir} does not exist; run \`mkdocs build --strict\` first`);
  } else {
    const indexPath = path.join(site, "index.html");
    if (!fs.existsSync(indexPath)) {
      fail("the built site has no index.html");
    } else {
      const index = fs.readFileSync(indexPath, "utf8");

      // The masthead override rendered. Without custom_dir, or with a template
      // that stopped emitting the lockup, Material falls back to its own icon
      // and nothing anywhere reports it.
      if (!index.includes("gw-signature-word")) {
        fail("the built index.html carries no masthead signature; the logo template did not render");
      }

      // Every local asset the built page names exists in the built site.
      const referenced = new Set();
      for (const m of index.matchAll(/<link[^>]+href="([^"]+)"/g)) referenced.add(m[1]);
      for (const m of index.matchAll(/<(?:img|script)[^>]+src="([^"]+)"/g)) referenced.add(m[1]);
      const local = [...referenced].filter(
        (r) => !/^(https?:)?\/\//.test(r) && !r.startsWith("data:"),
      );
      for (const ref of local) {
        if (!fs.existsSync(path.join(site, ref.replace(/[?#].*$/, "")))) {
          fail(`index.html references ${ref}, which the built site does not contain`);
        }
      }

      // The brand stylesheet is one of them. A theme whose extra_css was
      // dropped still builds, still passes everything above, and serves stock
      // Material.
      const brand = local.find((r) => r.endsWith(path.basename(MANIFEST.stylesheet)));
      if (!brand) {
        fail(
          `index.html links no ${path.basename(MANIFEST.stylesheet)}; `
            + "the theme's extra_css did not reach the page",
        );
      } else {
        // The faces the stylesheet names are present. They are self-hosted
        // precisely so no build depends on a font CDN, which is what makes a
        // missing file silent: the browser falls back to a system serif.
        const brandPath = path.join(site, brand);
        if (fs.existsSync(brandPath)) {
          const css = fs.readFileSync(brandPath, "utf8");
          const fonts = new Set([...css.matchAll(/url\("([^"]+\.woff2)"\)/g)].map((m) => m[1]));
          if (fonts.size === 0) fail(`${brand} declares no self-hosted font file`);
          for (const font of fonts) {
            if (!fs.existsSync(path.resolve(path.dirname(brandPath), font))) {
              fail(`${brand} names ${font}, which the built site does not contain`);
            }
          }
        }
      }
    }
  }
}

// ---- 3. This file is the one that was rendered ----------------------------

// The placeholder is assembled rather than written, so that the line the
// projector substitutes appears exactly once in this file. Spelling it out here
// too would give the substitution a second target, and rewriting both is how a
// generated check ends up comparing a digest against itself and passing
// unconditionally.
const PLACEHOLDER = "__EXPECTED" + "_DIGEST__";

const self = fs.readFileSync(fileURLToPath(import.meta.url), "utf8");
const selfDigest = crypto
  .createHash("sha256")
  .update(
    self.replace(
      `const SOURCE_DIGEST = "${SOURCE_DIGEST}";`,
      `const SOURCE_DIGEST = "${PLACEHOLDER}";`,
    ),
    "utf8",
  )
  .digest("hex");
if (selfDigest !== SOURCE_DIGEST) {
  fail("this check has been edited locally; it is generated by the GaugeWright repository");
}

if (failures.length > 0) {
  for (const f of failures) console.error(`docs theme: ${f}`);
  process.exit(1);
}

console.log(
  `docs theme check passed at sha256:${SOURCE_DIGEST.slice(0, 12)}… `
    + `(${Object.keys(MANIFEST.files).length} owned files, the shared block, and the built site).`,
);
